import React, { useState } from "react";
import { getAllNetflixLanguages } from "../api/netflixApi"; // 👈 Necesitamos este endpoint en tu api

const NetflixList = () => {
    const [languages, setLanguages] = useState([]);
    const [loading, setLoading] = useState(false);

    const handleFetchLanguages = async () => {
        setLoading(true);
        try {
            const res = await getAllNetflixLanguages(); // 👈 Llama a tu backend
            setLanguages(res.data);
        } catch (error) {
            console.error("Error al obtener lenguajes:", error);
            alert("No se pudo obtener la lista de lenguajes");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="mt-4">
            <h5>Lenguajes disponibles en Netflix API</h5>
            <div className="mb-3">
                <button className="btn btn-dark" onClick={handleFetchLanguages}>
                    Cargar Lenguajes
                </button>
            </div>

            {loading && <p>Cargando...</p>}

            <div className="table-responsive">
                <table className="table table-striped table-bordered">
                    <thead className="table-dark">
                        <tr>
                            <th>ID</th>
                            <th>Lenguaje</th>
                            <th>Código</th>
                            <th>Acciones</th>
                        </tr>
                    </thead>
                    <tbody>
                        {languages.length > 0 ? (
                            languages.map((lang, index) => (
                                <tr key={index}>
                                    <td>{lang.id || index}</td>
                                    <td>{lang.language || ""}</td>
                                    <td>{lang.code || ""}</td>
                                    <td>
                                        <button
                                            className="btn btn-outline-warning btn-sm"
                                            onClick={() =>
                                                navigator.clipboard.writeText(lang.language || "")
                                            }
                                            title="Copiar lenguaje"
                                        >
                                            Copiar Lenguaje
                                        </button>
                                    </td>
                                </tr>
                            ))
                        ) : (
                            <tr>
                                <td colSpan="4" className="text-center">
                                    No hay lenguajes disponibles
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default NetflixList;
